window.docContents[95].resolve({"/Induction/#Logical-Foundations--Induction___-Proof-by-Induction--Formal-vs___-Informal-Proof":{"contents":"\"Informal proofs are algorithms; formal proofs are code.\"\n\n\n\n\n\n\n\nTranslate your solution for add_comm into an informal proof:Theorem: Addition is commutative.Proof:\n\nWrite an informal proof of the following theorem, using the\ninformal proof of add_assoc as a model.  Don't just\nparaphrase the Lean tactics into English!Theorem: (n == n) = true for any n.Proof:\n\n","context":"Logical Foundations\u0009Induction: Proof by Induction","header":"3.4. Formal vs. Informal Proof","id":"/Induction/#Logical-Foundations--Induction___-Proof-by-Induction--Formal-vs___-Informal-Proof"}});